from itertools import product

def cyclic(m):
    return list(range(m)), (lambda a, b: (a + b) % m), (lambda a: (-a) % m), 0

def word_value(word, images, mul, inv, identity):
    acc = identity
    for gi, exp in word:
        g = images[gi]
        if exp < 0:
            g, exp = inv(g), -exp
        for _ in range(exp):
            acc = mul(acc, g)
    return acc

def enumerate_homs(r, relations, elems, mul, inv, identity):
    return [im for im in product(elems, repeat=r)
            if all(word_value(w, im, mul, inv, identity) == identity
                   for w in relations)]

elems, mul, inv, ident = cyclic(6)
print('Hom(Z, Z/6Z):', len(enumerate_homs(1, [], elems, mul, inv, ident)))

elems, mul, inv, ident = cyclic(4)
commutator = [(0, 1), (1, 1), (0, -1), (1, -1)]
print('Hom(Z^2, Z/4Z):', len(enumerate_homs(2, [commutator], elems, mul, inv, ident)))

