function EnumerateHoms(r, relations, H):
    homs <- empty list
    for each tuple images in H^r:            # |H|^r candidates
        ok <- true
        for each relation w in relations:
            if EvalWord(w, images, H) != identity(H):
                ok <- false; break
        if ok: append images to homs
    return homs

function EvalWord(w, images, H):
    acc <- identity(H)
    for (gen_index, exp) in w:
        g <- images[gen_index]
        if exp < 0: g <- inv(g); exp <- -exp
        repeat exp times: acc <- mul(acc, g)
    return acc

function EnumerateAdmissible(r, relations, family):
    seen <- empty set;  result <- empty list
    for idx, K in enumerate(family):
        for images in EnumerateHoms(r, relations, K):
            if images not in seen:
                add images to seen
                append (idx, images) to result
    return result

function ConjugacyClasses(homs, H):
    homset <- set(homs);  remaining <- set(homs);  classes <- []
    while remaining not empty:
        rep <- any element of remaining
        orbit <- { Conj(rep, m) : m in H } intersect homset
        append orbit to classes
        remaining <- remaining minus orbit
    return classes

function Conj(images, m):
    return ( mul(mul(m, x), inv(m)) for x in images )
